mapper.select:
SELECT o.sale_date AS saleDate, COUNT(DISTINCT o.id) AS saleCount, ROUND(SUM(i.amount), 2) AS saleAmount, ROUND(SUM(i.cost_amount), 2) AS costAmount, ROUND(SUM(i.amount) - SUM(i.cost_amount), 2) AS grossProfit FROM jxc_sale_order o JOIN jxc_sale_order_item i ON i.sale_id = o.id
AND o.status != '2'
AND o.sale_date >= #{beginDate}
AND o.sale_date <= #{endDate}
GROUP BY o.sale_date ORDER BY o.sale_date DESC

SELECT p.product_code AS productCode, p.product_name AS productName, p.unit AS unit, ROUND(SUM(i.quantity), 4) AS saleQty, ROUND(SUM(i.amount), 2) AS saleAmount, ROUND(SUM(i.cost_amount), 2) AS costAmount, ROUND(SUM(i.amount) - SUM(i.cost_amount), 2) AS grossProfit FROM jxc_sale_order_item i JOIN jxc_sale_order o ON i.sale_id = o.id LEFT JOIN jxc_product p ON i.product_id = p.id
AND o.status != '2'
AND o.sale_date >= #{beginDate}
AND o.sale_date <= #{endDate}
GROUP BY p.id, p.product_code, p.product_name, p.unit ORDER BY saleAmount DESC
